ct formulas"},{"id":"step-1","text":"Count atoms on each side"},{"id":"step-2","text":"Adjust coefficients"},{"id":"step-3","text":"Check atom counts again"}]},{"id":"chemistry.reactions.h.012","deckId":"chemistry.reactions","level":"hard","type":"diagram","prompt":"A fuel reacts rapidly with oxygen, forming products and releasing energy. Which general reaction type fits?","answer":"choice-1","options":[{"id":"choice-0","text":"Freezing","misconception":"chemistry.reactions.mixup.12.3"},{"id":"choice-1","text":"Combustion"},{"id":"choice-2","text":"Condensation","misconception":"chemistry.reactions.mixup.12.1"},{"id":"choice-3","text":"Filtration","misconception":"chemistry.reactions.mixup.12.2"}]},{"id":"earth.plates.e.001","deckId":"earth.plates","level":"easy","type":"mcq","prompt":"What broad zone of earthquakes and volcanoes includes much of the Philippines?","answer":"choice-0","options":[{"id":"choice-0","text":"Pacific Ring of Fire"},{"id":"choice-1","text":"Mid-Atlantic Ridge only","misconception":"earth.plates.mixup.1.1"},{"id":"choice-2","text":"Sahara Desert belt","misconception":"earth.plates.mixup.1.2"},{"id":"choice-3","text":"Arctic ice circle","misconception":"earth.plates.mixup.1.3"}]},{"id":"earth.plates.e.002","deckId":"earth.plates","level":"easy","type":"mcq","prompt":"What boundary is formed when plates move toward one another?","answer":"choice-1","options":[{"id":"choice-0","text":"Only a weather front","misconception":"earth.plates.mixup.2.3"},{"id":"choice-1","text":"Convergent"},{"id":"choice-2","text":"Divergent","misconception":"earth.plates.mixup.2.1"},{"id":"choice-3","text":"No plate boundary","misconception":"earth.plates.mixup.2.2"}]},{"id":"earth.plates.e.003","deckId":"earth.plates","level":"easy","type":"mcq","prompt":"What boundary has plates sliding past one another?","answer":"choice-2","options":[{"id":"choice-0","text":"Only collision without sliding","misconception":"earth.plates.mixup.3.2"},{"id":"choice-1","text":"Only v