,{"id":"choice-3","text":"Travel time","misconception":"physics.forces.mixup.2.2"}]},{"id":"physics.forces.e.003","deckId":"physics.forces","level":"easy","type":"mcq","prompt":"What can describe the forces between a person and a wall they push?","answer":"choice-2","options":[{"id":"choice-0","text":"The heavier one exerts all the force","misconception":"physics.forces.mixup.3.2"},{"id":"choice-1","text":"Same-direction forces only","misconception":"physics.forces.mixup.3.3"},{"id":"choice-2","text":"Equal and opposite forces"},{"id":"choice-3","text":"Only the person exerts a force","misconception":"physics.forces.mixup.3.1"}]},{"id":"physics.forces.e.004","deckId":"physics.forces","level":"easy","type":"mcq","prompt":"What is the sum of all forces on one object called?","answer":"choice-3","options":[{"id":"choice-0","text":"Single action-reaction pair","misconception":"physics.forces.mixup.4.1"},{"id":"choice-1","text":"Body volume","misconception":"physics.forces.mixup.4.2"},{"id":"choice-2","text":"Elapsed time","misconception":"physics.forces.mixup.4.3"},{"id":"choice-3","text":"Net force"}]},{"id":"physics.forces.e.005","deckId":"physics.forces","level":"easy","type":"mcq","prompt":"What happens when the net force on a moving object is zero?","answer":"choice-0","options":[{"id":"choice-0","text":"Velocity stays constant"},{"id":"choice-1","text":"Motion must stop at once","misconception":"physics.forces.mixup.5.1"},{"id":"choice-2","text":"Speed must rise","misconception":"physics.forces.mixup.5.2"},{"id":"choice-3","text":"Direction must reverse","misconception":"physics.forces.mixup.5.3"}]},{"id":"physics.forces.e.006","deckId":"physics.forces","level":"easy","type":"mcq","prompt":"What force opposes sliding between touching surfaces?","answer":"choice-1","options":[{"id":"choice-0","text":"Only air buoyancy","misconception":"physics.forces.mixup.6.3"},{"id":"choice-1","text":"Friction"},{"id":"choice-2","text":"Nuclear force","misconception":"physics.for